async function createDemo() {
  const path = "Image Atlas/Boas-vindas.imageboard";
  let file = app.vault.getFileByPath(path);
  if (!file) {
    const notePath = "Image Atlas/Exemplo/Estudo conectado.md";
    if (!app.vault.getFileByPath(notePath)) await app.vault.create(notePath, "# Estudo conectado\n\nUma nota re\xFAne seu resumo e seus flashcards. Ela pode aparecer em v\xE1rios quadros com o mesmo hist\xF3rico.\n\nComo estudar apenas as notas de um quadro? == Use **Estudar todos os flashcards** e escolha um tema.\nComo preservar uma c\xF3pia da biblioteca? == Use **Exportar c\xF3pia** na barra lateral.\n");
    const node = (id, title, x3, y3, parentId = "", body = "") => ({ id, type: "mind", title, body, x: x3, y: y3, w: 260, h: 150, mapId: "atlas-intro", parentId, color: "#a78bfa", flashcards: [] });
    const board = { version: 1, title: "Boas-vindas ao ROMUS", indexPath: "", camera: { x: 55, y: 80, z: 0.8 }, edges: [], nodes: [node("atlas-intro", "Conhecimento conectado", 20, 160, "", "Seu espa\xE7o de estudo visual."), node("ideas", "Mapeie suas ideias", 410, 35, "atlas-intro", "Tab cria um filho. Renomeie, mova e recolha os ramos."), node("review", "Estude com o FSRS", 410, 300, "atlas-intro", "Cada nota tem seu pr\xF3prio hist\xF3rico. O quadro re\xFAne os temas para revisar."), { id: "summary", type: "note", title: "Estudo conectado", path: notePath, x: 810, y: 100, w: 360, h: 280 }] };
    file = await app.vault.create(path, JSON.stringify(board, null, 2));
  }
  await app.workspace.getLeaf("tab").openFile(file);
}
async function openMediaLibrary() {
  const current2 = app.workspace.getLeavesOfType("atlas-media-library")[0];
  if (current2) return app.workspace.revealLeaf(current2);
  await app.workspace.getLeaf("tab").setViewState({ type: "atlas-media-library", state: {} });
}
async function openNotesLibrary() {
  const current2 = app.workspace.getLeavesOfType("atlas-notes-library")[0];
  if (current2) return app.workspace.revealLeaf(current2);
  await app.workspace.getLeaf("tab").setViewState({ type: "atlas-notes-library", state: {}, active: true });
}
function rememberWorkspace() {
  app.navigation?.capture();
  const tabs = app.workspace.leaves.map((leaf) => ({ path: leaf.view?.file?.path, type: leaf.view?.getViewType(), state: leaf.view?.getState?.(), review: leaf.view?.sessionSnapshot?.(), partner: app.workspace.leaves.indexOf(leaf.splitPartner), cursor: leaf.view?.input?.selectionStart, end: leaf.view?.input?.selectionEnd, scroll: leaf.view?.input?.scrollTop, focused: leaf.view?.input === document.activeElement }));
  localStorage.setItem("atlas:workspace:" + app.info.library, JSON.stringify({ tabs, layout: app.panes.serialize(), active: app.workspace.leaves.indexOf(app.workspace.activeLeaf) }));
}
async function restoreWorkspace() {
  let saved;
  try {
    saved = JSON.parse(localStorage.getItem("atlas:workspace:" + app.info.library) || "null");
  } catch {
    return;
  }
  if (!saved?.tabs?.length) return;
  const restored = [];
  for (const entry of saved.tabs) {
    try {
      let leaf;
      if (entry.type === "atlas-board-summary" || entry.type === "atlas-flashcard-editor") {
        leaf = app.workspace.getLeaf("tab");
        await leaf.setViewState({ type: entry.type, state: entry.state || {} });
      } else if (entry.path) {
        const file = app.vault.getFileByPath(entry.path);
        if (!file) continue;
        leaf = app.workspace.getLeaf("tab");
        await leaf.openFile(file);
        if (entry.state?.mode && leaf.view.setEditorMode) await leaf.view.setEditorMode(entry.state.mode);
        if (entry.state?.showStudy && leaf.view.toggleStudyContent) await leaf.view.toggleStudyContent();
      } else if (entry.type === "atlas-notes-library") {
        leaf = app.workspace.getLeaf("tab");
        await leaf.setViewState({ type: entry.type, state: entry.state || {} });
      } else if (["atlas-media-library", "atlas-media-player"].includes(entry.type)) {
        leaf = app.workspace.getLeaf("tab");
        await leaf.setViewState({ type: entry.type, state: entry.state || {} });
      } else if (entry.type === "image-atlas-flashcards") {
        leaf = await plugin.openReviewTab(entry.state, entry.review);
      }
      if (!leaf) continue;
      if (leaf.view.input && typeof entry.cursor === "number") {
        leaf.view.input.setSelectionRange(entry.cursor, entry.end ?? entry.cursor);
        leaf.view.input.scrollTop = entry.scroll || 0;
      }
      restored.push({ leaf, entry });
    } catch (error) {
      new Notice("N\xE3o foi poss\xEDvel reabrir uma aba: " + error.message);
    }
  }
  if (saved.layout) app.panes.restore(saved.layout, saved.tabs.map((entry) => restored.find((item) => item.entry === entry)?.leaf));
  for (const { leaf, entry } of restored) {
    const partner = restored.find((item) => item.entry === saved.tabs[entry.partner]);
    if (partner) leaf.splitPartner = partner.leaf;
  }
  const current2 = restored[Math.min(saved.active, restored.length - 1)];
  if (current2) {
    await app.workspace.revealLeaf(current2.leaf);
    if (current2.entry.focused && current2.leaf.view.input) {
      current2.leaf.view.input.focus({ preventScroll: true });
      current2.leaf.view.input.dispatchEvent(new Event("click"));
    }
  }
}
var updatePending;
var updateTimer;
var lastTyping = 0;
window.addEventListener("input", () => {
  lastTyping = Date.now();
}, true);
async function applyDevelopmentUpdate() {
  clearTimeout(updateTimer);
  if (!updatePending) return;
  if (modalsOpen()) return;
  if (document.body.classList.contains("atlas-dragging-note") || document.body.classList.contains("atlas-dragging-board")) {
    updateTimer = setTimeout(applyDevelopmentUpdate, 350);
    return;
  }
  if (Date.now() - lastTyping < 1e3) {
    updateTimer = setTimeout(applyDevelopmentUpdate, 1e3);
    return;
  }
  try {
    await flush();
    rememberWorkspace();
    const kind = updatePending;
    updatePending = null;
    if (kind === "backend") native.restartDevelopment();
    else location.reload();
  } catch (error) {
    new Notice("Atualiza\xE7\xE3o aguardando salvar: " + error.message);
  }
}
native.onUpdate?.((_3, kind) => {
  if (kind === "styles") {
    for (const link of document.querySelectorAll("link[rel=stylesheet]")) {
      const url = new URL(link.href);
      url.searchParams.set("v", Date.now());
      link.href = url.href;
    }
    return;
  }
  updatePending = kind === "backend" ? "backend" : updatePending || "renderer";
  if (modalsOpen()) new Notice("Atualiza\xE7\xE3o pronta. Ser\xE1 aplicada quando voc\xEA fechar esta janela de edi\xE7\xE3o.");
  else updateTimer = setTimeout(applyDevelopmentUpdate, 350);
});
window.addEventListener("atlas:modal-closed", () => {
  if (updatePending) updateTimer = setTimeout(applyDevelopmentUpdate, 350);
});
